INSERT INTO movie (title, description, cover_image_url) VALUES ('Habeas Corpus', 'Uma renomada ex-criminalista lidera um grupo de estudantes de Direito para provar a inocência de um jovem condenado injustamente, enquanto segredos do passado ameaçam o caso.', 'https://images.ctfassets.net/4cd45et68cgf/1dcXzfMqBR6fYtvbNZZgLc/446d7e07462f1327ecd1997a63f57ab4/pt_BR_BR_HCO_Main_Vertical_27x40_RGB_PRE.jpg?w=1200');